func (v ListUsersByStatusView) Source(status db.UserStatus) sqlcx.BoundView {
	return v.Bind(status)
}

func scanListUsersByStatusView(m *db.User) []any {
	return []any{&m.ID, &m.Email, &m.Name, &m.Nickname, &m.Age, &m.Status, &m.PrevStatus, &m.Balance, &m.Score, &m.Administrator, &m.Tags, &m.Meta, &m.Settings, &m.ExternalID, &m.ManagerID, &m.Birthday, &m.CreatedAt}
}
